-- 420_intake_xjz_csharp_client_recovered_service_ports.sql
-- Purpose: intake the 2026-08-18 XJZ C# client-recovered service contract map as readable research evidence.
-- Boundary: this is client-recovered C# contract evidence, not official packet proof and not final gameplay constants.

CREATE TABLE IF NOT EXISTS god2_research.xjz_csharp_evidence_pack_intake (
  pack_id VARCHAR(96) NOT NULL,
  source_zip_path VARCHAR(512) NOT NULL,
  evidence_kind VARCHAR(96) NOT NULL,
  service_port_count INT NOT NULL,
  database_table_count INT NOT NULL,
  csharp_contract_file_count INT NOT NULL,
  apply_boundary TEXT NOT NULL,
  created_at_utc TIMESTAMP NOT NULL DEFAULT UTC_TIMESTAMP(),
  PRIMARY KEY (pack_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS god2_research.xjz_csharp_service_port_bindings (
  service_area VARCHAR(128) NOT NULL,
  cpp_contracts VARCHAR(512) NOT NULL,
  csharp_contracts VARCHAR(512) NOT NULL,
  port_status VARCHAR(64) NOT NULL,
  game_function_category VARCHAR(96) NOT NULL,
  apply_status VARCHAR(256) NOT NULL,
  server_mapping VARCHAR(256) NOT NULL,
  source_pack_id VARCHAR(96) NOT NULL,
  created_at_utc TIMESTAMP NOT NULL DEFAULT UTC_TIMESTAMP(),
  PRIMARY KEY (service_area),
  KEY idx_xjz_csharp_service_port_category (game_function_category),
  KEY idx_xjz_csharp_service_port_pack (source_pack_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS god2_research.xjz_csharp_apply_queue (
  queue_key VARCHAR(96) NOT NULL,
  game_function_zh_tw VARCHAR(128) NOT NULL,
  client_recovered_evidence_zh_tw VARCHAR(512) NOT NULL,
  safe_apply_level_zh_tw VARCHAR(128) NOT NULL,
  next_server_action_zh_tw VARCHAR(512) NOT NULL,
  blocked_reason_zh_tw VARCHAR(512) NULL,
  source_pack_id VARCHAR(96) NOT NULL,
  PRIMARY KEY (queue_key),
  KEY idx_xjz_csharp_apply_queue_level (safe_apply_level_zh_tw)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

