INSERT INTO god2_research.xjz_csharp_apply_queue
(queue_key,game_function_zh_tw,client_recovered_evidence_zh_tw,safe_apply_level_zh_tw,next_server_action_zh_tw,blocked_reason_zh_tw,source_pack_id)
VALUES
('item_effect_rules','道具使用效果','客戶端還原出 96 筆 item_effect_rule，其中 19 類 handler 可轉成補血、補魔、清狀態、能力 Buff、學技能、傳送、餵寵物或坐騎。','可優先實裝候選','比對 god2_game.item_effects/item_usage_rules 與 ItemUseEffectEngine，只套用 handler 語意明確者。',NULL,'XJZ-csharp-evidence-capture-pack-20260818'),
('npc_shop_slots','NPC 商店販售格','客戶端還原 gamedata_npc_item_shop_slot 非空格 2265 筆、distinct item 573、shop list 190。','可建立候選，正式綁定需補證','匯入研究候選表並比對 god2_game.items；NPC 與 shop_list_id 的正式綁定等官方封包或黑箱測試。','NPC 綁定與價格公式仍是封包邊界。','XJZ-csharp-evidence-capture-pack-20260818'),
('monster_visual_and_targets','怪物外觀與抓包目標','客戶端還原 215 筆 monster_visual_template、monster_stat_capture_target 與 monster_skill_probe_template。','可建立外觀/抓包目標','可補怪物外觀與觀測清單；不直接覆蓋正式 HP/MP/攻防。','最終怪物 HP/MP 與戰鬥數值需要官方封包或黑箱測試。','XJZ-csharp-evidence-capture-pack-20260818'),
('quest_reward_targets','任務獎勵抓包目標','客戶端還原 418 筆 quest_reward_capture_target，但 quest_reward 與 claim sample 仍為 0。','只能建待抓清單','保留任務獎勵抓包目標；正式 quest_rewards 不硬填。','沒有直接任務獎勵樣本。','XJZ-csharp-evidence-capture-pack-20260818'),
('combat_contracts','戰鬥與技能服務契約','C# 契約涵蓋技能、傷害、治療、復活、Buff/Debuff、五行、回合 tick 與戰鬥命令。','可比對服務端結構','比對 Runtime 戰鬥服務已實作項；公式常數以真實測試資料優先。','最終傷害公式、命中、暴擊、五行倍率仍需黑箱測試。','XJZ-csharp-evidence-capture-pack-20260818');
